(function(E){ const x = E["sales-m1"] = E["sales-m1"] || {units:{}}; x.units["sales-1-2"] = {"grammar":{"id":"c-sales-1-2-g","level":"B1","course":"sales","unit":"sales-1-2","title":"Polite questions: Could you tell me when he is...?","titleTr":"Kibar sorular: Could you tell me when he is...?","titleFa":"سؤال مؤدبانه: Could you tell me when he is...?","formsTable":{"headers":{"en":["Direct (can sound rude)","Polite (statement order)"],"tr":["Doğrudan (kaba duyulabilir)","Kibar (düz cümle sırası)"],"fa":["مستقیم (ممکن است بی‌ادبانه باشد)","مؤدبانه (ترتیب جمله‌ی خبری)"]},"rows":[["When is she free?","Could you tell me when she is free?"],["Where does she work?","Do you know where she works?"],["Is she in today?","Do you know if she is in today?"],["Who buys spices?","Could you tell me who buys spices?"]]},"wrong":"Could you tell me when is Ms Novak free?","right":"Could you tell me when Ms Novak is free?","blank":{"sentence":"Could you tell me when Ms Novak ___ back from her meeting?","word":"will be","distractors":["will she be","does be"]},"wrong2":"Do you know does she speak English?","right2":"Do you know if she speaks English?","blank2":{"sentence":"Do you know ___ she is in the office today?","word":"if","distractors":["is","does"]},"expParts":{"tryFrom":"blank","rule":[{"en":"The opener is already the question, so use subject + verb, with no do or did.","tr":"Baştaki kalıp zaten sorudur; bu yüzden özne + fiil kullan, do ya da did getirme.","fa":"عبارت اول خودش سؤال است؛ پس اول فاعل و بعد فعل بیاور و do یا did نگذار.","ex":"Could you tell me when she is free?"},{"en":"A yes/no question has no question word, so add if.","tr":"Evet/hayır sorusunda soru kelimesi yoktur; bu yüzden if ekle.","fa":"سؤال بله/خیر کلمه‌ی پرسشی ندارد؛ پس if اضافه کن.","ex":"Do you know if she is in today?"},{"en":"'I'd like to know' is a statement, so end with a full stop.","tr":"'I'd like to know' soru değil, düz cümledir; bu yüzden noktayla bitir.","fa":"عبارت I'd like to know جمله‌ی خبری است، نه پرسشی؛ پس با نقطه تمامش کن.","ex":"I'd like to know who buys your spices."}],"test":{"en":"Cover the opener. Does the rest look like a statement, such as 'he is' or 'he works'? Then it's right.","tr":"Girişi kapat. Geri kalanı 'he is' ya da 'he works' gibi düz bir cümleye mi benziyor? O zaman doğru.","fa":"شروع مؤدبانه را بپوشان. بقیه‌اش شبیه جمله‌ی خبری است، مثل he is یا he works؟ پس درست است."},"contrast":{"en":"Turkish uses a verb ending and Persian keeps direct-question order, so learners keep 'when is he'. English goes back to 'when he is'.","tr":"Türkçede bu yapı fiil ekiyle kurulur: 'Ne zaman döneceğini söyleyebilir misiniz?' Bu yüzden İngilizcede doğrudan soru sırası ('when is he') aynen kalıyor. İngilizcede kibar girişten sonra düz cümle sırasına dönülür: 'when he is'.","fa":"در فارسی سؤال غیرمستقیم همان ترتیب سؤال مستقیم را دارد: «می‌دانید کِی برمی‌گردد؟». برای همین خیلی از ما می‌گوییم when is he. در انگلیسی بعد از شروع مؤدبانه، ترتیب به جمله‌ی خبری برمی‌گردد: when he is."}},"errorWatch":[{"find":["tell me when is","tell me where is","tell me when does","tell me where does","tell me what is his","tell me what is her","tell me what time does","know when is","know where is","know when does","know where does","know what time does"],"fix":{"en":"Inside a polite question, use statement order: 'Could you tell me when she is free?'","tr":"Kibar soruda düz cümle sırası kullan: 'Could you tell me when she is free?'","fa":"داخل سؤال مؤدبانه، ترتیب جمله‌ی خبری را به کار ببر: «Could you tell me when she is free?»"}},{"find":["know does he","know does she","know is he","know is she","know can he","know will he","know do you"],"fix":{"en":"For a yes/no question after 'Do you know', use if: 'Do you know if she is in today?'","tr":"'Do you know'dan sonra evet/hayır sorusu için if kullan: 'Do you know if she is in today?'","fa":"برای سؤال بله/خیر بعد از «Do you know» از if استفاده کن: «Do you know if she is in today?»"}}]},"b2":{"id":"c-sales-1-2-b2","level":"B2","track":"B2","course":"sales","unit":"sales-1-2","title":"Extra-soft openers: I was wondering if..., Would you happen to know...?","titleTr":"Daha da yumuşak girişler: I was wondering if..., Would you happen to know...?","titleFa":"شروع‌های نرم‌تر: I was wondering if...، Would you happen to know...?","formsTable":{"headers":{"en":["Opener","Then statement order"],"tr":["Giriş","Ardından düz cümle sırası"],"fa":["شروع","بعد ترتیب جمله‌ی خبری"]},"rows":[["I was wondering if","you could put me through to her."],["I was wondering whether","she has time for a short call."],["Would you happen to know","when she is back?"],["Would you happen to know","who I should speak to?"]]},"wrong":"I was wondering if could you put me through to Ms Novak.","right":"I was wondering if you could put me through to Ms Novak.","blank":{"sentence":"I was wondering if you ___ give me her email address.","word":"could","distractors":["can to","could to"]},"wrong2":"Would you happen to know who should I speak to?","right2":"Would you happen to know who I should speak to?","blank2":{"sentence":"Would you happen to know when Ms Novak ___ free this week?","word":"is","distractors":["is she","does"]},"expParts":{"tryFrom":"blank2","rule":[{"en":"I was wondering if + you could + verb: a polite request now.","tr":"I was wondering if + you could + fiil: şimdi için kibar bir rica.","fa":"بعد از I was wondering if you could فعل ساده می‌آید و این درخواستی مؤدبانه برای همین حالاست.","ex":"I was wondering if you could put me through."},{"en":"Would you happen to know + question word + subject + verb?","tr":"Would you happen to know + soru kelimesi + özne + fiil?","fa":"بعد از Would you happen to know اول کلمه‌ی پرسشی می‌آید، بعد فاعل و بعد فعل.","ex":"Would you happen to know when she is back?"},{"en":"Never put the verb before the subject after these openers.","tr":"Bu girişlerden sonra fiili asla öznenin önüne koyma.","fa":"بعد از این شروع‌ها هیچ‌وقت فعل را قبل از فاعل نیاور.","ex":"... who I should speak to, not who should I"}],"test":{"en":"Read what comes after 'if' or the question word. If it sounds like a question, change it into a statement.","tr":"'if'ten ya da soru kelimesinden sonra geleni oku. Soru gibi duyuluyorsa düz cümleye çevir.","fa":"بخش بعد از if یا کلمه‌ی پرسشی را بخوان. اگر شبیه سؤال است، آن را به جمله‌ی خبری تبدیل کن."},"contrast":{"en":"Turkish softens with '-ebilir misiniz acaba' and Persian with «ممکن است لطفاً...؟», both still questions. English B2 softening uses a statement ('I was wondering if...') or a hedge ('happen to'), with statement order after it.","tr":"Türkçede '...verebilir misiniz acaba?' diyerek yumuşatırız; cümle yine soru olarak kalır. İngilizcede B2 seviyesinde yumuşatma düz bir cümleyle ('I was wondering if...') ya da 'happen to' ile yapılır ve ardından düz cümle sırası gelir.","fa":"در فارسی با «ممکن است لطفاً...؟» درخواست را نرم می‌کنیم و جمله همچنان سؤالی است. در انگلیسیِ B2 نرم کردن با یک جمله‌ی خبری (I was wondering if...) یا با happen to انجام می‌شود و بعدش ترتیب جمله‌ی خبری می‌آید."}},"errorWatch":[{"find":["wondering if could","wondering whether could","wondering if can you","wondering if would you","happen to know who should i","happen to know where is","happen to know when is"],"fix":{"en":"After these openers, use statement order: 'I was wondering if you could...', 'Would you happen to know who I should speak to?'","tr":"Bu girişlerden sonra düz cümle sırası kullan: 'I was wondering if you could...', 'Would you happen to know who I should speak to?'","fa":"بعد از این شروع‌ها ترتیب جمله‌ی خبری را به کار ببر: «I was wondering if you could...» و «Would you happen to know who I should speak to?»"}}],"useIn":{"en":"B2: in the call or the note, use 'I was wondering if you could...' or 'Would you happen to know...?' once.","tr":"B2: aramada ya da notta 'I was wondering if you could...' ya da 'Would you happen to know...?' kalıbını bir kez kullan.","fa":"مسیر B2: در تماس یا یادداشت، یک بار از I was wondering if you could... یا Would you happen to know...? استفاده کن."},"exitItem":{"from":"sales-1-2","kind":"blank","prompt":"I was wondering ___ you could tell your buyer that I called.","options":["that","if","what"],"correct":1}},"vocab":{"id":"c-sales-1-2-v","level":"B1","category":"vocab","course":"sales","unit":"sales-1-2","goals":["career"],"title":{"en":"Making contact","tr":"Temas kurmak","fa":"تماس گرفتن"},"cards":[{"word":"put through","sentence":"Could you put me through to the sales office, please?","gap":"put me through","accept":["put me through","put through"],"meaning":{"en":"To connect a caller to another person's phone.","tr":"telefonu birine bağlamak.","fa":"وصل کردن تماس به کسی"}},{"word":"extension","sentence":"Her extension is 214, but she is in a meeting.","meaning":{"en":"The short number of one phone inside a company.","tr":"dahili numara.","fa":"شماره‌ی داخلی"}},{"word":"procurement","sentence":"Most hotels have a procurement team that compares suppliers.","meaning":{"en":"Buying goods and services for a company.","tr":"satın alma, tedarik.","fa":"تدارکات؛ خرید کالا و خدمات برای شرکت"}},{"word":"in charge of","sentence":"Who is in charge of buying spices?","meaning":{"en":"Responsible for something.","tr":"-den sorumlu.","fa":"مسئولِ (کاری)"}},{"word":"call back","sentence":"Could she call me back this afternoon?","gap":"call me back","accept":["call me back","call back"],"meaning":{"en":"To phone someone who phoned you.","tr":"geri aramak.","fa":"در جواب تماس کسی، به او زنگ زدن"}},{"word":"leave a message","sentence":"Would you like to leave a message for him?","meaning":{"en":"To ask someone to pass on your words.","tr":"mesaj bırakmak.","fa":"پیغام گذاشتن"}},{"word":"available","sentence":"The buyer is not available until three o'clock.","meaning":{"en":"Free to talk or meet.","tr":"müsait.","fa":"در دسترس؛ آزاد برای صحبت"}},{"word":"suggest","sentence":"A colleague suggested I call you.","gap":"suggested","accept":["suggested"],"meaning":{"en":"To give someone an idea of what to do.","tr":"önermek.","fa":"پیشنهاد کردن"}},{"word":"mention","sentence":"Please mention the fair in your email.","meaning":{"en":"To say something briefly.","tr":"adını anmak, bahsetmek.","fa":"اشاره کردن؛ نام بردن"}},{"word":"prospect","sentence":"This chain is a good prospect for our dates.","meaning":{"en":"A company that may become a customer.","tr":"potansiyel müşteri.","fa":"مشتری بالقوه"}}]},"judge":{"id":"c-sales-1-2-j","course":"sales","unit":"sales-1-2","type":"judge","title":{"en":"Would you answer this?","tr":"Buna cevap verir miydin?","fa":"تو به این جواب می‌دادی؟"},"prompt":"Four first emails to the buyer of a chain of food shops.","parts":["Real reason","Short","Small request"],"instruction":{"en":"Tap what each email does well. The one to send does all three.","tr":"Her e-postanın iyi yaptığı şeylere dokun. Gönderilecek olan üçünü de yapar.","fa":"روی کارهایی که هر ایمیل درست انجام داده بزن. ایمیلی که باید بفرستی هر سه را دارد."},"items":[{"by":"AI tool","answer":"I hope this email finds you well. In today's competitive market, partnering with the right supplier is more important than ever. We would love to explore synergies with your esteemed company.","present":[],"fix":{"en":"It could go to anyone, and it asks for nothing clear. Name one fact about them and one small step.","tr":"Herkese gidebilir ve açık bir şey istemiyor. Onlarla ilgili bir gerçek ve küçük bir adım söyle.","fa":"می‌شود آن را برای هر کسی فرستاد و چیز روشنی نمی‌خواهد. یک واقعیت درباره‌ی آن‌ها و یک قدم کوچک بگو."}},{"by":"New rep","answer":"Please see our price list and send your order for 500 cartons.","present":["Short"],"fix":{"en":"Short, but a stranger won't order 500 cartons. Give a reason and ask for a sample first.","tr":"Kısa ama bir yabancı 500 koli sipariş etmez. Bir neden söyle ve önce numune teklif et.","fa":"کوتاه است، ولی هیچ غریبه‌ای ۵۰۰ کارتن سفارش نمی‌دهد. دلیل بیاور و اول نمونه پیشنهاد کن."}},{"by":"Sales rep","answer":"You opened three shops this year, and your website shows no dried figs. We have supplied figs to food shops since 2012, in several sizes and grades, from orchards we have worked with for years, with cartons for every shelf and every season. Our whole range is on our site.","present":["Real reason"],"fix":{"en":"A real reason, but too long, and no request. Cut it to two lines and ask for one thing.","tr":"Gerçek bir neden var ama çok uzun ve istek yok. İki satıra indir ve tek bir şey iste.","fa":"دلیل واقعی دارد، ولی خیلی بلند است و درخواستی ندارد. آن را به دو خط کوتاه کن و یک چیز بخواه."}},{"by":"Good model","answer":"You opened three shops this year, and your website shows no dried figs. We supply figs to shops like yours. Could I send you two samples?","present":["Real reason","Short","Small request"],"fix":null}]},"speaking":{"id":"sales-1-2","course":"sales","unit":"sales-1-2","topic":{"en":"Getting through, or leaving a message","tr":"Doğru kişiye ulaşmak ya da mesaj bırakmak","fa":"رسیدن به آدم درست، یا پیام گذاشتن"},"warmup":{"en":"Who answers the phone at a company you want to sell to? What do they need to hear from you?","tr":"Satış yapmak istediğin şirkette telefona kim bakar? Senden ne duymak ister?","fa":"در شرکتی که می‌خواهی به آن بفروشی چه کسی تلفن را جواب می‌دهد؟ باید چه چیزی از تو بشنود؟"},"questions":[{"en":"Say who you are and why you are calling, in one sentence. Then ask who buys your type of product.","tr":"Kim olduğunu ve neden aradığını tek cümlede söyle. Sonra senin ürün türünü kimin satın aldığını sor.","fa":"در یک جمله بگو چه کسی هستی و چرا زنگ زده‌ای. بعد بپرس چه کسی این نوع محصول را می‌خرد."},{"en":"You hear: 'She's in a meeting.' Ask when she is free, and ask for her email address.","tr":"Şunu duyuyorsun: 'She's in a meeting.' Ne zaman müsait olduğunu sor ve e-posta adresini iste.","fa":"می‌شنوی: «She's in a meeting.» بپرس کی وقتش آزاد است و آدرس ایمیلش را بخواه."},{"en":"Leave a voicemail in under 20 seconds: name, company, reason, one request, your number twice.","tr":"20 saniyenin altında sesli mesaj bırak: ad, şirket, neden, bir istek, numaran iki kez.","fa":"زیر ۲۰ ثانیه پیام صوتی بگذار: اسم، شرکت، دلیل، یک درخواست و شماره‌ات دو بار."}],"followups":[{"en":"Now plan a real call to a company you want as a customer. What is your first sentence?","tr":"Şimdi müşterin olmasını istediğin bir şirketi gerçekten aramayı planla. İlk cümlen ne?","fa":"حالا برای یک تماس واقعی با شرکتی که می‌خواهی مشتری‌ات شود برنامه بریز. جمله‌ی اولت چیست؟"}],"expressions":[{"phrase":"The reason I'm calling is ...","meaning":{"en":"Gives the reason early.","tr":"Nedeni baştan söyler.","fa":"دلیل را زود می‌گوید."}},{"phrase":"Could you tell me who ...?","meaning":{"en":"Asks politely for the right person.","tr":"Doğru kişiyi kibarca sorar.","fa":"مؤدبانه آدم درست را می‌پرسد."}},{"phrase":"When would be a good time to call back?","meaning":{"en":"Lets you call again later.","tr":"Sonra yeniden aramanı sağlar.","fa":"امکان تماس دوباره را برایت نگه می‌دارد."}}],"model":"Good morning. My name is Sara, from a dried fruit exporter in Izmir. The reason I'm calling is that your shops don't sell figs yet. Could you tell me who buys dried fruit? I see. Do you know when she is free? Thank you. Could I also have her email address, so I can send her a short note? Thanks for your help.","selfCheck":[{"en":"I gave my reason in the first two sentences.","tr":"Nedenimi ilk iki cümlede söyledim.","fa":"دلیلم را در دو جمله‌ی اول گفتم."},{"en":"I used statement order after Could you tell me.","tr":"Could you tell me'den sonra düz cümle sırası kullandım.","fa":"بعد از Could you tell me ترتیب جمله‌ی خبری را به کار بردم."},{"en":"I was friendly to the person who answered.","tr":"Telefonu açan kişiye karşı nazik davrandım.","fa":"با کسی که جواب داد خوش‌رو بودم."},{"en":"I ended with a clear next step.","tr":"Net bir sonraki adımla bitirdim.","fa":"با یک قدم بعدی روشن تمام کردم."}]},"writing":{"id":"c-sales-1-2-w","course":"sales","unit":"sales-1-2","type":"writing","difficulty":"medium","modelBy":"FEschool","title":{"en":"Your first email and contact note","tr":"İlk e-postan ve temas notun","fa":"ایمیل اول و یادداشت تماس تو"},"portfolio":null,"prompt":{"en":"Choose a real company you want as a customer, or a chain of tea shops in Poland that sells no saffron tea (you pack saffron tea in Mashhad). Write a first email (40-60 words): one real fact, why you are writing, one small request. Then add a two-line note for your own records: who you wrote to, and when you will follow up.","tr":"Müşterin olmasını istediğin gerçek bir şirket ya da Polonya'da safran çayı satmayan bir çay dükkânı zinciri seç (sen Meşhed'de safran çayı paketliyorsun). İlk e-postanı yaz (40-60 kelime): gerçek bir bilgi, neden yazdığın, küçük bir istek. Sonra kendi kayıtların için iki satırlık not ekle: kime yazdın, ne zaman takip edeceksin.","fa":"یک شرکت واقعی که می‌خواهی مشتری‌ات شود، یا یک فروشگاه زنجیره‌ای چای در لهستان را که چای زعفرانی نمی‌فروشد انتخاب کن (تو در مشهد چای زعفرانی بسته‌بندی می‌کنی). ایمیل اول را بنویس (۴۰ تا ۶۰ کلمه): یک واقعیت، چرا می‌نویسی، یک درخواست کوچک. بعد یک یادداشت دوخطی برای خودت اضافه کن: به چه کسی نوشتی و کی پیگیری می‌کنی."},"model":"Dear Mr Kowalski,\n\nI saw on your website that your tea shops don't sell saffron tea yet. We pack saffron tea in Mashhad for small shops in Europe. Could I send you ten sample boxes next week?\n\nBest regards\n\nNote: wrote to Mr Kowalski, head buyer, on 4 May. Follow up on 9 May with the price sheet.","frame":"Dear ___,\n\nI saw ___. We ___ for ___. Could I send you ___?\n\nBest regards\n\nNote: wrote to ___ on ___. Follow up on ___ with ___.","words":[{"word":"I saw"},{"word":"Could I"},{"word":"Follow up"}],"minWords":40,"minSentences":3,"rubric":["Task done: a real fact, a reason, one request, and a note with a follow-up date","Organised: their fact first, then you, then the request","Language: polite questions in the right word order","Tone: short and human, no mass-email phrases"],"rubricI18n":{"tr":["Görev: gerçek bir bilgi, bir neden, bir istek ve takip tarihli bir not","Düzen: önce onlarla ilgili bilgi, sonra sen, sonra istek","Dil: doğru sıralı kibar sorular","Üslup: kısa ve insani, toplu e-posta kalıpları yok"],"fa":["کامل بودن کار: یک واقعیت، یک دلیل، یک درخواست و یادداشتی با تاریخ پیگیری","نظم: اول واقعیت درباره‌ی آن‌ها، بعد خودت، بعد درخواست","زبان: سؤال‌های مؤدبانه با ترتیب درست","لحن: کوتاه و انسانی، بدون جمله‌های ایمیل انبوه"]}},"exit":{"id":"c-sales-1-2-x","course":"sales","unit":"sales-1-2","type":"exit","items":[{"from":"sales-1-2","kind":"blank","prompt":"Could you tell me what time the warehouse ___ on Fridays?","options":["close","does it close","closes"],"correct":2,"point":2},{"from":"sales-1-2","kind":"mcq","prompt":"Which line is best for a first email?","options":["Please place your order this week, while our price is still low.","I saw you opened a shop in Lyon. Could I send you a sample?","We are the leading exporter in the region, with 20 years behind us."],"correct":1,"point":1},{"from":"sales-1-2","kind":"mcq","prompt":"A buyer doesn't reply to your first email. What is the best next step?","options":["Write \"Any news?\" every day until they answer.","Stop for good, because they are not interested.","Write again a few days later with something new."],"correct":2,"point":1},{"from":"sales-1-1","kind":"blank","prompt":"Our cases fold flat, which ___ they fit in any van.","options":["mean","is meaning","means"],"correct":2},{"from":"sales-1-1","kind":"blank","prompt":"The screws are stainless, so you can ___ them outdoors.","options":["use","to use","using"],"correct":0},{"from":"sales-1-1","kind":"mcq","prompt":"Which word means \"a fact about what a product has or does\"?","options":["benefit","feature","supplier"],"correct":1}]},"explain":{"id":"c-sales-1-2-e","course":"sales","unit":"sales-1-2","type":"explain","level":"B1","title":{"en":"First contact: the call and the first email","tr":"İlk temas: arama ve ilk e-posta","fa":"اولین تماس: تلفن و ایمیل اول"},"objective":{"en":"In this lesson you will learn to make first contact with a new company: find the right person, say why you are writing or calling, and ask for one small step.","tr":"Bu derste yeni bir şirketle ilk teması kurmayı öğreneceksin: doğru kişiyi bulmak, neden aradığını ya da yazdığını söylemek ve küçük bir adım istemek.","fa":"در این درس یاد می‌گیری با یک شرکت تازه اولین تماس را بگیری: آدم درست را پیدا کنی، بگویی چرا تماس گرفته‌ای یا نوشته‌ای و یک قدم کوچک بخواهی."},"hook":{"en":"A first contact has one job: to get a second contact. Nobody orders from a stranger after one message, so don't try to sell yet.","tr":"İlk temasın tek işi vardır: ikinci teması sağlamak. Kimse tek mesajla bir yabancıdan sipariş vermez; o yüzden henüz satmaya çalışma.","fa":"اولین تماس فقط یک هدف دارد: جور کردن تماس دوم. هیچ‌کس با یک پیام از غریبه سفارش نمی‌دهد؛ پس هنوز برای فروش تلاش نکن."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The sales skill","tr":"Satış becerisi","fa":"مهارت فروش"},"head":{"en":"Four moves for any first contact","tr":"Her ilk temas için dört adım","fa":"چهار قدم برای هر اولین تماس"},"steps":[{"en":"Find one real fact about them first. It shows this is not a mass email.","tr":"Önce onlar hakkında gerçek bir bilgi bul. Bu, mesajının toplu e-posta olmadığını gösterir.","fa":"اول یک واقعیت درباره‌ی آن‌ها پیدا کن. این نشان می‌دهد پیامت ایمیل انبوه نیست.","ex":"You opened two new shops in Hamburg this year."},{"en":"Say who you are and why them, in one sentence. Busy people stop reading quickly.","tr":"Kim olduğunu ve neden onları seçtiğini tek cümlede söyle. Yoğun insanlar okumayı çabuk bırakır.","fa":"در یک جمله بگو چه کسی هستی و چرا سراغ آن‌ها آمده‌ای. آدم‌های پرمشغله زود از خواندن دست می‌کشند.","ex":"We supply dried fruit to shops like yours."},{"en":"Ask the receptionist politely who buys this. They know the name you need.","tr":"Santraldeki kişiye bunu kimin satın aldığını kibarca sor. İhtiyacın olan adı o bilir.","fa":"مؤدبانه از منشی بپرس چه کسی مسئول خرید این کالاست. اسمی را که لازم داری او می‌داند.","ex":"Could you tell me who buys dried fruit?"},{"en":"Ask for one small thing: a sample, or fifteen minutes. A small yes is easy.","tr":"Tek küçük şey iste: bir numune ya da on beş dakika. Küçük bir evet kolaydır.","fa":"یک چیز کوچک بخواه: یک نمونه، یا پانزده دقیقه وقت. «بله» گفتن به چیز کوچک آسان است.","ex":"Would fifteen minutes on Tuesday work?"}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"Polite questions: Could you tell me when he is...?","tr":"Kibar sorular: Could you tell me when he is...?","fa":"سؤال مؤدبانه: Could you tell me when he is...?"},"steps":[{"en":"The opener is already the question, so use subject + verb, with no do or did.","tr":"Baştaki kalıp zaten sorudur; bu yüzden özne + fiil kullan, do ya da did getirme.","fa":"عبارت اول خودش سؤال است؛ پس اول فاعل و بعد فعل بیاور و do یا did نگذار.","ex":"Could you tell me when she is free?"},{"en":"A yes/no question has no question word, so add if.","tr":"Evet/hayır sorusunda soru kelimesi yoktur; bu yüzden if ekle.","fa":"سؤال بله/خیر کلمه‌ی پرسشی ندارد؛ پس if اضافه کن.","ex":"Do you know if she is in today?"},{"en":"'I'd like to know' is a statement, so end with a full stop.","tr":"'I'd like to know' soru değil, düz cümledir; bu yüzden noktayla bitir.","fa":"عبارت I'd like to know جمله‌ی خبری است، نه پرسشی؛ پس با نقطه تمامش کن.","ex":"I'd like to know who buys your spices."}],"table":{"headers":{"en":["Direct (can sound rude)","Polite (statement order)"],"tr":["Doğrudan (kaba duyulabilir)","Kibar (düz cümle sırası)"],"fa":["مستقیم (ممکن است بی‌ادبانه باشد)","مؤدبانه (ترتیب جمله‌ی خبری)"]},"rows":[["When is she free?","Could you tell me when she is free?"],["Where does she work?","Do you know where she works?"],["Is she in today?","Do you know if she is in today?"],["Who buys spices?","Could you tell me who buys spices?"]]},"tip":{"en":"Turkish uses a verb ending and Persian keeps direct-question order, so learners keep 'when is he'. English goes back to 'when he is'.","tr":"Türkçede bu yapı fiil ekiyle kurulur: 'Ne zaman döneceğini söyleyebilir misiniz?' Bu yüzden İngilizcede doğrudan soru sırası ('when is he') aynen kalıyor. İngilizcede kibar girişten sonra düz cümle sırasına dönülür: 'when he is'.","fa":"در فارسی سؤال غیرمستقیم همان ترتیب سؤال مستقیم را دارد: «می‌دانید کِی برمی‌گردد؟». برای همین خیلی از ما می‌گوییم when is he. در انگلیسی بعد از شروع مؤدبانه، ترتیب به جمله‌ی خبری برمی‌گردد: when he is."}},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Calls, emails and the follow-up","tr":"Aramalar, e-postalar ve takip","fa":"تماس، ایمیل و پیگیری"},"body":{"en":"No reply is normal, so write again a few days later with something new, not 'any news?'. Keep voicemails to 20 seconds. Keep a note of every contact, and check local rules on unasked-for sales emails.","tr":"Cevap gelmemesi normaldir; birkaç gün sonra 'any news?' diye değil, yeni bir şeyle yeniden yaz. Sesli mesajı 20 saniyede tut. Her temasın notunu al ve istenmeyen satış e-postalarıyla ilgili yerel kuralları kontrol et.","fa":"جواب نگرفتن عادی است؛ چند روز بعد با چیزی تازه دوباره بنویس، نه با «any news?». پیام صوتی را زیر ۲۰ ثانیه نگه دار. از هر تماس یادداشت بردار و قانون‌های محلی درباره‌ی ایمیل فروش ناخواسته را بررسی کن."},"phrases":[{"phrase":"The reason I'm calling is ...","meaning":{"en":"Gives the reason early.","tr":"Nedeni baştan söyler.","fa":"دلیل را زود می‌گوید."}},{"phrase":"Could you tell me who ...?","meaning":{"en":"Asks politely for the right person.","tr":"Doğru kişiyi kibarca sorar.","fa":"مؤدبانه آدم درست را می‌پرسد."}},{"phrase":"When would be a good time to call back?","meaning":{"en":"Lets you call again later.","tr":"Sonra yeniden aramanı sağlar.","fa":"امکان تماس دوباره را برایت نگه می‌دارد."}},{"phrase":"prospect","meaning":{"en":"A company that may become a customer.","tr":"potansiyel müşteri.","fa":"مشتری بالقوه"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"A first email that gets read","tr":"Okunan bir ilk e-posta","fa":"ایمیل اولی که خوانده می‌شود"},"item":"Dear Sir or Madam, we are a big exporter with 20 years of experience. Please see our 40-page catalogue attached and send us your order. Your facts: the buyer is Ms Novak; she opened two shops in Hamburg this year; you supply dried fruit.","answer":"Dear Ms Novak, I saw that you opened two shops in Hamburg this year. We supply dried fruit to shops like yours. Could I send you three samples?","walk":[{"en":"Use a real name and a real fact, so it isn't a mass email.","tr":"Gerçek bir ad ve gerçek bir bilgi kullan; toplu e-posta gibi durmasın.","fa":"اسم واقعی و واقعیتی درباره‌ی او بیاور تا شبیه ایمیل انبوه نباشد."},{"en":"Cut the company history and the attachment. Keep it under 100 words.","tr":"Şirket tarihini ve eki çıkar. 100 kelimenin altında tut.","fa":"تاریخچه‌ی شرکت و پیوست را حذف کن و متن را زیر ۱۰۰ کلمه نگه دار."},{"en":"Ask for a sample, not an order. A small yes comes first.","tr":"Sipariş değil, numune iste. Önce küçük bir evet gelir.","fa":"نمونه بخواه، نه سفارش؛ چون اول باید یک «بله»ی کوچک بگیری."}]},"quick":{"prompt":"The goal of a first contact is to get ___.","options":["a second contact","a full order","a lower price"],"correct":0,"why":{"en":"a second contact: nobody orders from a stranger in one email. Ask for a small next step.","tr":"a second contact: kimse tek e-postayla bir yabancıdan sipariş vermez. Küçük bir sonraki adım iste.","fa":"جواب a second contact است، چون هیچ‌کس با یک ایمیل از غریبه سفارش نمی‌دهد. پس یک قدم بعدی کوچک بخواه."}},"remember":{"en":"One real fact, one reason, one small request. You can now write a first email or make a first call that asks for one small step.","tr":"Bir gerçek bilgi, bir neden, küçük bir istek. Artık küçük bir adım isteyen bir ilk e-posta yazabilir ya da ilk aramayı yapabilirsin.","fa":"یک واقعیت درباره‌ی او بگو، یک دلیل بیاور و یک چیز کوچک بخواه. حالا می‌توانی ایمیل اول را بنویسی یا تماس اول را بگیری و یک قدم کوچک بخواهی."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Extra-soft openers: I was wondering if..., Would you happen to know...?","tr":"Daha da yumuşak girişler: I was wondering if..., Would you happen to know...?","fa":"شروع‌های نرم‌تر: I was wondering if...، Would you happen to know...?"},"steps":[{"en":"I was wondering if + you could + verb: a polite request now.","tr":"I was wondering if + you could + fiil: şimdi için kibar bir rica.","fa":"بعد از I was wondering if you could فعل ساده می‌آید و این درخواستی مؤدبانه برای همین حالاست.","ex":"I was wondering if you could put me through."},{"en":"Would you happen to know + question word + subject + verb?","tr":"Would you happen to know + soru kelimesi + özne + fiil?","fa":"بعد از Would you happen to know اول کلمه‌ی پرسشی می‌آید، بعد فاعل و بعد فعل.","ex":"Would you happen to know when she is back?"},{"en":"Never put the verb before the subject after these openers.","tr":"Bu girişlerden sonra fiili asla öznenin önüne koyma.","fa":"بعد از این شروع‌ها هیچ‌وقت فعل را قبل از فاعل نیاور.","ex":"... who I should speak to, not who should I"}],"table":{"headers":{"en":["Opener","Then statement order"],"tr":["Giriş","Ardından düz cümle sırası"],"fa":["شروع","بعد ترتیب جمله‌ی خبری"]},"rows":[["I was wondering if","you could put me through to her."],["I was wondering whether","she has time for a short call."],["Would you happen to know","when she is back?"],["Would you happen to know","who I should speak to?"]]},"body":{"en":"B2: in the call or the note, use 'I was wondering if you could...' or 'Would you happen to know...?' once.","tr":"B2: aramada ya da notta 'I was wondering if you could...' ya da 'Would you happen to know...?' kalıbını bir kez kullan.","fa":"مسیر B2: در تماس یا یادداشت، یک بار از I was wondering if you could... یا Would you happen to know...? استفاده کن."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
